import org.araqne.log.api.http.HttpPostLogService;

@Component(name = "http-post-logger-factory")
@Provides
public class HttpPostLoggerFactory extends AbstractLoggerFactory {

	@Requires
	private HttpPostLogService postLog;

	@Override
	public String getName() {
		return "http-post";
	}

	@Override
	public List<Locale> getLocales() {
		return Arrays.asList(Locale.ENGLISH, Locale.KOREAN);
	}

	@Override
	public String getDisplayGroup(Locale locale) {
		return "HTTP";
	}

	@Override
	public String getDisplayName(Locale locale) {
		return "HTTP POST";
	}

	@Override
	public String getDescription(Locale locale) {
		if (locale != null && locale.equals(Locale.KOREAN))
			return "HTTP POST를 통해 로그를 수신합니다.";
		return "Collect logs through HTTP POST";
	}

	@Override
	public Collection<LoggerConfigOption> getConfigOptions() {
		LoggerConfigOption callback = new MutableStringConfigType("callback", t("Callback", "콜백 이름"), t(
				"Name for /log/CALLBACK endpoint", "/log/콜백이름"), true);
		return Arrays.asList(callback);
	}

	private Map<Locale, String> t(String enText, String koText) {
		Map<Locale, String> m = new HashMap<Locale, String>();
		m.put(Locale.ENGLISH, enText);
		m.put(Locale.KOREAN, koText);
		return m;
	}

	@Override
	protected Logger createLogger(LoggerSpecification spec) {
		return new HttpPostLogger(spec, this, postLog);
	}

}

def accession(result):
    """
    Produce the accession for the result. This will compute the accession
    depending on the database.
    """

    if result["database"] == "ENA" or result["database"] == "HGNC":
        return result["accession"]
    if result["database"] == "PDBE":
        return "%s_%s" % (result["external_id"], result["optional_id"])
    return result["external_id"]

import { Component, OnInit } from '@angular/core';
import { Http, Headers, RequestOptions } from '@angular/http';
import {Router} from '@angular/router';
import { LoginService } from '../login/login.service';
import { Inject, Injectable } from '@angular/core';
import { DOCUMENT } from '@angular/platform-browser';

@Component({
  selector: 'app-admin-usuarios',
  templateUrl: './admin-usuarios.component.html'
})
export class AdminUsuariosComponent implements OnInit {

  private usuarios : Object [] = [];
  private domain;
  constructor( @Inject(DOCUMENT) private document: any, private http: Http, private router: Router, private loginService: LoginService) { 
    this.domain=this.document.location.hostname;
  }

  ngOnInit() {
    this.cargarUsuarios();
  }

  cargarUsuarios(){
    const headers = new Headers({
            'X-Requested-With': 'XMLHttpRequest'
    });
    const options = new RequestOptions({ withCredentials: true, headers });
    let url = "https://"+this.domain+":8443/rest/admin/users";
      this.http.get(url, options).subscribe(
        response => {
          let data = response.json();
          for (var i=0; i< data.length; i++){
            this.usuarios.push(data[i]);
          }
          console.log(this.usuarios);

  },
        error => console.error(error)
      );
  }

}

